const sharedPoolStatement=(env,id=SHARED_POOL_ID)=>env.DB.prepare('INSERT INTO character_pools(id,pools_json) VALUES(?,?) ON CONFLICT(id) DO NOTHING').bind(id,JSON.stringify(GENERATION_POOLS));
